        if atom[0] == 'clear':
            state[atom[1]] = {'clear': True, 'on': None, 'ontop': None}
        elif atom[0] == 'on':
            state[atom[1]] = state.get(atom[1], {})
            state[atom[1]]['on'] = atom[2]
            state[atom[2]] = state.get(atom[2], {})
            state[atom[2]]['ontop'] = atom[1]
        elif atom[0] == 'ontop':
            # This is already handled by 'on'
            pass
        elif atom[0] == 'handempty':
            state['hand'] = None
        elif atom[0] == 'holding':
            state['hand'] = atom[1]
    # Initialize missing blocks
    all_blocks = ['red', 'blue', 'orange', 'brown', 'white', 'black', 'green', 'yellow', 'cyan', 'purple', 'pink', 'magenta', 'black']
    for block in all_blocks:
        if block not in state:
            state[block] = {'clear': True, 'on': None, 'ontop': None}
    return state

